import{_ as i,l as d,o as a,c,v as o,p as l,x as r,d as n,i as s,S as E}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"资源获取即初始化","description":"","frontmatter":{"title":"资源获取即初始化","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/raii.md","filePath":"cs/raii.md","lastUpdated":1789023840000}'),p={name:"cs/raii.md"};function h(B,e,A,u,_,m){const t=d("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="资源获取即初始化" tabindex="-1">资源获取即初始化 <a class="header-anchor" href="#资源获取即初始化" aria-label="Permalink to &quot;资源获取即初始化&quot;">​</a></h1><div class="epigraph"><p>谁获取资源，谁在对象寿命结束时释放；把获取写进初始化、把释放写进收尾，失败路径才不会漏。</p><footer>—— 据 ISO/IEC 9899；Kernighan &amp; Ritchie, The C Programming Language, 2nd ed. 整理</footer></div><p>上一课<a href="/cs/vtable-preview">动态分派与虚表</a>让销毁可以走表项。本课不重讲间接调用，也不从 C++ 教材名词另起。缺口是：错误码课已经要求失败时回滚，悬挂课已经要求 <code>free</code> 配对——<strong>怎样让「获取与释放」跟对象寿命自动对齐</strong>，而不是在每一条 <code>return</code> 上抄一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文件描述符、堆块、锁、映射区都是资源：获取成功后必须有人释放，否则泄漏；释放后必须无人再使用，否则悬挂。缺口因此不是再列 API，而是<strong>把资源的寿命绑定到某个对象的寿命</strong>。该对象初始化失败则资源未获取；初始化成功则销毁（或显式 <code>close</code>）一定会走到。C 没有析构语法，但同一纪律可以用结构体加唯一销毁函数、或 <code>goto cleanup</code> 单一出口来实现。</p><p>RAII 这个名字来自 C++：构造获取，析构释放，栈展开也会跑析构。本栏用它指纪律，而不是引入异常。单出口清理在 C 里是同一思想的手工版。测试失败路径时，应能断言：错误返回后无泄漏、无双释放。</p><h3 id="raii-不是垃圾回收" tabindex="-1">RAII 不是垃圾回收 <a class="header-anchor" href="#raii-不是垃圾回收" aria-label="Permalink to &quot;RAII 不是垃圾回收&quot;">​</a></h3><p>垃圾回收回收的是内存，时机不确定，也不自动关闭套接字。RAII 是确定性的：对象寿命结束即释放，包括栈上自动对象离开作用域。把两者混成「都不用管释放」，会在描述符和锁上泄漏。C 里没有自动析构，更要把销毁函数当成公开契约的一部分。</p><p><span class="marginnote">ISO C 只提供寿命，不提供析构钩子。K&amp;R 的程序靠纪律配对 <code>fopen</code>/<code>fclose</code>。本课把那条纪律提升为对象边界上的不变量：活对象拥有资源，死对象不再拥有。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个拥有资源的类型：创建函数内部获取，失败则释放已拿到的部分并返回错误；销毁函数释放全部并结束对象寿命。调用方不直接 <code>free</code> 内部指针。需要提前释放时只走销毁，不提供第二条路径。栈上的包装可以用一个带销毁语义的辅助，在函数所有 <code>return</code> 前调用——单一 <code>cleanup</code> 标签是常见写法。</p>',11)),(a(),l(E,null,{default:r(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22%E5%88%9D%E5%A7%8B%E5%8C%96%EF%BC%9A%E8%8E%B7%E5%8F%96%E8%B5%84%E6%BA%90%22%5D%20--%3E%20LIVE%5B%22%E5%AF%B9%E8%B1%A1%E6%B4%BB%E7%9D%80%E5%8D%B3%E6%8B%A5%E6%9C%89%22%5D%0A%20%20LIVE%20--%3E%20USE%5B%22%E5%85%AC%E5%BC%80%E6%93%8D%E4%BD%9C%22%5D%0A%20%20LIVE%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%EF%BC%9A%E4%BB%8D%E8%B5%B0%E9%94%80%E6%AF%81%22%5D%0A%20%20LIVE%20--%3E%20END%5B%22%E5%AF%BF%E5%91%BD%E7%BB%93%E6%9D%9F%22%5D%0A%20%20END%20--%3E%20REL%5B%22%E9%87%8A%E6%94%BE%E5%B9%B6%E7%BB%93%E6%9D%9F%E6%89%80%E6%9C%89%E6%9D%83%22%5D%0A%20%20FAIL%20--%3E%20REL%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>所有权转移（创建者把对象交给调用方）必须在契约里写明：此后由接收者销毁。禁止两边各 <code>free</code> 一次。这与函数边界课的所有权声明是同一句话，现在落到资源上。</p><p>文件、锁、映射区比堆块更不能靠进程结束来「顺便清」：长期进程会先耗尽描述符。把它们绑到对象，才能在早返回、错误码、将来可能的线程取消上共用一个销毁点。C++ 异常展开会跑析构，C 没有这条；因此本栏不把异常当默认失败通道。测试应当在失败注入后查描述符与堆的余额，而不仅查返回码。后课共享可变会禁止两个对象同时拥有同一描述符而不声明协议。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>绑定之后，失败路径不再是特殊的漏扫：任何离开活状态的出口都经过同一释放。泄漏变成「创建成功却未把所有权交给任何人」，双释放变成「两个主人」。封装保证调用方碰不到内部句柄去提前 <code>close</code>。后课共享可变会问：两个线程各以为自己是主人时，这条绑定如何被打破——本课先在单线程把主人唯一钉死。</p><p>C++ 析构让这条纪律由编译器在每个作用域出口插入调用；C 必须把出口收敛。<code>goto cleanup</code> 不是风格落后，是在没有析构时维持唯一释放点。早 <code>return</code> 散落各处时，新加的资源获取几乎必然漏一条路径。测试失败注入的价值正在于逼出这些路径。所有权转移（把已初始化对象交给调用方）之后，创建者不得再销毁——双主人比无主人更接近双释放。共享可变课会问两个指针同时当主人怎么办；本课的答案是：那时已经不是 RAII，而是共享。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲智能指针图，不讲循环引用。下一课<a href="/cs/shared-mutable-preview">并发之前：共享可变</a>讨论多个名字同时写同一对象。后课默认：资源有唯一主人；创建与销毁配对；失败与成功出口都经过释放。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资源寿命绑到对象寿命：初始化获取，结束时释放。</li><li>C 用唯一销毁函数或单一清理出口模拟，而不是靠垃圾回收。</li><li>所有权转移必须在契约上换主人，禁止双释放。</li><li>下一课看多个可变别名如何在并发之前就毁掉不变量。</li><li>出处：ISO C 对象寿命；K&amp;R 对 <code>fopen</code>/<code>fclose</code> 的配对；RAII 作为纪律而非语法。</li></ul>',9))])}const C=i(p,[["render",h]]);export{I as __pageData,C as default};
